//! Golden vectors of XXH3 and the plane-hash layout `rehoboam/rh-snapshot/hash/v1` (SPR-007 T-01).
//!
//! `tests/golden/rh_snapshot_hash_v1.txt` is generated by `bin/gen_hash_golden.py`, an
//! independent standard-library implementation of XXH3 and the layout; this test reproduces every
//! line with `twox-hash` and `rh_snapshot::hash`. A mismatch means the layout or the hash changed,
//! which is a C3 change; the golden file is never edited by hand. Hash stability across runs and
//! machines follows: the expected values are fixed text.
//!
//! REF: `crates/rh-snapshot/src/hash.rs` (the layout); Architect ruling 1 of SPR-007.
#![allow(clippy::unwrap_used, clippy::panic, reason = "tests")]

use std::collections::BTreeMap;

use rh_core::world::WorldTables;
use rh_snapshot::hash::{Plane, PlaneDigest, TableDigest, plane_hash, tables_hash, xxh3, xxh3_128};

const GOLDEN: &str = include_str!("golden/rh_snapshot_hash_v1.txt");
const GAMMA: u64 = 0x9E37_79B9_7F4A_7C15;

fn input_bytes(len: usize) -> Vec<u8> {
    (0..len)
        .map(|j| u8::try_from((131 * j + len) & 0xFF).unwrap())
        .collect()
}

fn column(salt: u64, rows: usize) -> Vec<i64> {
    (0..rows as u64)
        .map(|i| ((i + 1).wrapping_mul(GAMMA) ^ salt).cast_signed())
        .collect()
}

fn bytes_rows(rows: usize) -> Vec<Vec<u8>> {
    (0..rows)
        .map(|i| vec![u8::try_from(i & 0xFF).unwrap(); i % 7])
        .collect()
}

fn hex64(s: &str) -> u64 {
    u64::from_str_radix(s, 16).unwrap()
}

fn plane_of(letter: &str) -> Plane {
    match letter {
        "A" => Plane::A,
        "B" => Plane::B,
        "C" => Plane::C,
        other => panic!("unknown plane {other}"),
    }
}

fn check_table(line: &str, digest: &TableDigest, expected: &[&str]) {
    assert_eq!(digest.root, hex64(expected[0]), "root: {line}");
    let chunks: Vec<u64> = expected[1..].iter().map(|h| hex64(h)).collect();
    assert_eq!(digest.chunks, chunks, "chunks: {line}");
}

#[test]
fn every_golden_line_reproduces() {
    let mut counts: BTreeMap<&str, usize> = BTreeMap::new();
    for line in GOLDEN.lines().filter(|l| !l.starts_with('#')) {
        let f: Vec<&str> = line.split(' ').collect();
        *counts.entry(f[0]).or_default() += 1;
        match f[0] {
            "xxh3_64" => {
                let data = input_bytes(f[1].parse().unwrap());
                assert_eq!(xxh3(&data), hex64(f[2]), "{line}");
            }
            "xxh3_128" => {
                let data = input_bytes(f[1].parse().unwrap());
                let expected = u128::from_str_radix(f[2], 16).unwrap().to_be_bytes();
                assert_eq!(xxh3_128(&data), expected, "{line}");
            }
            "column" => {
                let rows = column(f[2].parse().unwrap(), f[3].parse().unwrap());
                check_table(line, &TableDigest::of(f[1], rows.as_slice()), &f[4..]);
            }
            "bytes" => {
                let rows = bytes_rows(f[2].parse().unwrap());
                check_table(line, &TableDigest::of(f[1], rows.as_slice()), &f[3..]);
            }
            "plane" => {
                let plane = plane_of(f[1]);
                let t: usize = f[2].parse().unwrap();
                let mut tables = BTreeMap::new();
                for k in 0..t {
                    let name = f[3 + 3 * k];
                    let rows = column(f[4 + 3 * k].parse().unwrap(), f[5 + 3 * k].parse().unwrap());
                    tables.insert(name.to_owned(), TableDigest::of(name, rows.as_slice()));
                }
                let expected = hex64(f[3 + 3 * t]);
                let roots: Vec<(&str, u64)> =
                    tables.iter().map(|(n, d)| (n.as_str(), d.root)).collect();
                assert_eq!(plane_hash(plane, roots).unwrap(), expected, "{line}");
                assert_eq!(
                    PlaneDigest::from_tables(plane, tables.clone()).hash,
                    expected
                );
                if plane == Plane::A {
                    // The same tables as world columns: their `tables_hash` is this plane hash.
                    let mut world = WorldTables::new();
                    for k in 0..t {
                        let rows =
                            column(f[4 + 3 * k].parse().unwrap(), f[5 + 3 * k].parse().unwrap());
                        world.insert(f[3 + 3 * k], rows);
                    }
                    assert_eq!(tables_hash(&world), expected, "{line}");
                }
            }
            "engine_table" => {
                let tables = rh_snapshot::state::engine_tables(&synthetic_state());
                let (_, rows) = tables
                    .iter()
                    .find(|(n, _)| *n == f[1])
                    .unwrap_or_else(|| panic!("no engine table {}", f[1]));
                assert_eq!(rows.len(), f[2].parse::<usize>().unwrap(), "{line}");
                check_table(line, &TableDigest::of(f[1], rows.as_slice()), &f[3..]);
            }
            "engine" => {
                assert_eq!(
                    rh_snapshot::state_hash(&synthetic_state()),
                    hex64(f[1]),
                    "{line}"
                );
            }
            other => panic!("unknown golden record {other:?}"),
        }
    }
    // Every record kind is present, so an empty or truncated file cannot pass.
    assert_eq!(counts.get("xxh3_64"), Some(&268));
    assert_eq!(counts.get("xxh3_128"), Some(&268));
    assert_eq!(counts.get("column"), Some(&7));
    assert_eq!(counts.get("bytes"), Some(&4));
    assert_eq!(counts.get("plane"), Some(&6));
    assert_eq!(counts.get("engine_table"), Some(&8));
    assert_eq!(counts.get("engine"), Some(&1));
}

/// The synthetic engine state of `bin/gen_hash_golden.py` (`SYNTHETIC_STATE`, `SYNTHETIC_WORLD`),
/// built with the Rust types: every engine table has rows.
#[allow(
    clippy::too_many_lines,
    reason = "one literal state, kept side by side with the Python reference's"
)]
fn synthetic_state() -> rh_core::state::EngineState {
    use rh_core::agenda::{AgendaKey, AgendaState, Timer, TimerId};
    use rh_core::command::{Command, CommandQueuesState, QueuedCommand};
    use rh_core::engine::MaterialInput;
    use rh_core::phase::Phase;
    use rh_core::time::SimTime;
    use rh_events::{DraftRef, Event, EventLogState};
    use rh_ids::{EntityKind, EntityRef, EventId, PersonId, PurposeId, SystemId, TimelineId};
    const DAY: i64 = 1_440;
    let e = EntityRef::new;
    let t = SimTime::from_minutes;
    let timer = |time, phase: usize, entity, seq, owner, purpose, kind, payload| {
        (
            AgendaKey {
                time: t(time),
                phase: Phase::ALL[phase],
                entity,
                seq,
            },
            Timer {
                owner: SystemId::from_raw(owner),
                purpose: PurposeId::from_raw(purpose),
                kind,
                payload,
            },
        )
    };
    let command = |person, seq, sender, cause, args: Vec<i64>, draft| QueuedCommand {
        tick: t(DAY),
        phase: Phase::ALL[3],
        seq,
        sender,
        cause,
        command: Command {
            kind: "Inherit",
            person: PersonId::from_raw(person),
            args,
            cause: draft,
        },
    };
    let mut world = WorldTables::new();
    world.insert("pop.count", column(21, 5));
    world.insert("vital.alive", column(22, 1030));
    rh_core::state::EngineState {
        cursor: Some(t(40 * DAY + 7)),
        timeline: TimelineId::from_raw(3),
        accepted_inputs: 2,
        tables: world,
        agenda: AgendaState {
            entries: vec![
                timer(100, 4, e(EntityKind::Person, 7), 2, 11, 0xABC, 1, -5),
                timer(100, 4, e(EntityKind::Person, 9), 0, 11, 0xABC, 2, 7),
                timer(250, 1, e(EntityKind::Household, 3), 5, 12, 0xDEF, 3, 0),
            ],
            next_seq: 6,
            tombstones: vec![TimerId::from_raw(5)],
        },
        commands: CommandQueuesState {
            queues: vec![(
                "X2.estate",
                vec![
                    command(
                        7,
                        4,
                        "X1.vital",
                        Some(EventId::from_raw(12)),
                        vec![1, -2],
                        Some(DraftRef(0)),
                    ),
                    command(8, 8, "X5.war", None, vec![], None),
                ],
            )],
            next_seq: 9,
        },
        epochs: vec![
            (e(EntityKind::Person, 7), 1),
            (e(EntityKind::Household, 3), 2),
        ],
        inputs: vec![
            (
                t(45 * DAY + 3),
                vec![
                    MaterialInput {
                        scope: [e(EntityKind::Person, 1), e(EntityKind::Person, 6)].into(),
                    },
                    MaterialInput::default(),
                ],
            ),
            (
                t(400 * DAY),
                vec![MaterialInput {
                    scope: [e(EntityKind::Region, 2)].into(),
                }],
            ),
        ],
        events: EventLogState {
            events: vec![
                Event {
                    id: EventId::from_raw(18),
                    tick: 57_600,
                    phase: 4,
                    emitter: "X1.vital",
                    kind: "DEATH",
                    subjects: vec![e(EntityKind::Person, 7)],
                    causes: vec![EventId::from_raw(3)],
                    payload: vec![1],
                },
                Event {
                    id: EventId::from_raw(19),
                    tick: 57_603,
                    phase: 9,
                    emitter: "X4.census",
                    kind: "CENSUS",
                    subjects: vec![],
                    causes: vec![],
                    payload: vec![-1, 40],
                },
            ],
            next_seq: 20,
            last: Some((57_603, 9)),
            running: 0x1234_5678_9ABC_DEF0,
        },
    }
}
